CREATE TABLE en1991_document(
id INTEGER PRIMARY KEY,
annex TEXT NOT NULL CHECK(annex IN ('En','De')), snow_zone TEXT NOT NULL,
altitude REAL, en_sk REAL, north_german_lowland_snow INTEGER NOT NULL CHECK(north_german_lowland_snow IN (0,1)),
wind_zone INTEGER NOT NULL CHECK(wind_zone>=0 AND wind_zone<=255), en_vb REAL,
terrain_category INTEGER NOT NULL CHECK(terrain_category>=0 AND terrain_category<=255),
mixed_terrain_upwind INTEGER NOT NULL CHECK(mixed_terrain_upwind>=0 AND mixed_terrain_upwind<=255),
mixed_terrain_distance REAL, orography_factor REAL, coast_or_island INTEGER NOT NULL CHECK(coast_or_island IN (0,1)),
air_density REAL, height REAL, width REAL, depth REAL, assumed_delta_t REAL, t_max REAL, t_min REAL, t_0 REAL,
thermal_element_type TEXT NOT NULL, thermal_bridge_type INTEGER NOT NULL CHECK(thermal_bridge_type>=0 AND thermal_bridge_type<=255),
delta_t_m REAL, storey_count INTEGER NOT NULL CHECK(storey_count>=0 AND storey_count<=255),
fire_mode TEXT NOT NULL CHECK(fire_mode IN ('none','nominal','parametric')),
fire_curve TEXT NOT NULL CHECK(fire_curve IN ('standard','external','hydrocarbon','parametric')),
fire_duration REAL, assumed_gas_temperature REAL, assumed_h_net REAL, fire_compartment_area REAL,
fire_compartment_height REAL, fire_opening_factor REAL, fire_thermal_inertia REAL, fire_occupancy TEXT NOT NULL,
fire_load_density_qf REAL, assumed_qf_d REAL, construction_activity TEXT NOT NULL, assumed_construction_qk REAL,
structure_kind TEXT NOT NULL CHECK(structure_kind IN ('building','bridge')),
bridge_lane INTEGER NOT NULL CHECK(bridge_lane>=0 AND bridge_lane<=255),
bridge_span REAL, bridge_lane_width REAL, assumed_bridge_tandem REAL, assumed_bridge_udl REAL,
assumed_bridge_lm2 REAL, assumed_bridge_footway REAL, assumed_bridge_lm3 REAL, assumed_bridge_lm4 REAL,
bridge_load_group TEXT NOT NULL, crane_claimed INTEGER NOT NULL CHECK(crane_claimed IN (0,1)),
crane_class TEXT NOT NULL, hoist_class TEXT NOT NULL, hoisting_speed REAL, assumed_crane_wheel REAL, assumed_crane_horizontal REAL,
silo_claimed INTEGER NOT NULL CHECK(silo_claimed IN (0,1)), silo_kind TEXT NOT NULL,
silo_bulk_density REAL, silo_height REAL, silo_hydraulic_radius REAL, silo_mu REAL, silo_k REAL,
assumed_silo_pressure REAL, assumed_silo_patch REAL, assumed_silo_wall_friction REAL,
altitude_ieee754_bits INTEGER NOT NULL, altitude_ieee754_class TEXT NOT NULL,
en_sk_ieee754_bits INTEGER NOT NULL, en_sk_ieee754_class TEXT NOT NULL,
en_vb_ieee754_bits INTEGER NOT NULL, en_vb_ieee754_class TEXT NOT NULL,
mixed_terrain_distance_ieee754_bits INTEGER NOT NULL, mixed_terrain_distance_ieee754_class TEXT NOT NULL,
orography_factor_ieee754_bits INTEGER NOT NULL, orography_factor_ieee754_class TEXT NOT NULL,
air_density_ieee754_bits INTEGER NOT NULL, air_density_ieee754_class TEXT NOT NULL,
height_ieee754_bits INTEGER NOT NULL, height_ieee754_class TEXT NOT NULL,
width_ieee754_bits INTEGER NOT NULL, width_ieee754_class TEXT NOT NULL,
depth_ieee754_bits INTEGER NOT NULL, depth_ieee754_class TEXT NOT NULL,
assumed_delta_t_ieee754_bits INTEGER NOT NULL, assumed_delta_t_ieee754_class TEXT NOT NULL,
t_max_ieee754_bits INTEGER NOT NULL, t_max_ieee754_class TEXT NOT NULL,
t_min_ieee754_bits INTEGER NOT NULL, t_min_ieee754_class TEXT NOT NULL,
t_0_ieee754_bits INTEGER NOT NULL, t_0_ieee754_class TEXT NOT NULL,
delta_t_m_ieee754_bits INTEGER NOT NULL, delta_t_m_ieee754_class TEXT NOT NULL,
fire_duration_ieee754_bits INTEGER NOT NULL, fire_duration_ieee754_class TEXT NOT NULL,
assumed_gas_temperature_ieee754_bits INTEGER NOT NULL, assumed_gas_temperature_ieee754_class TEXT NOT NULL,
assumed_h_net_ieee754_bits INTEGER NOT NULL, assumed_h_net_ieee754_class TEXT NOT NULL,
fire_compartment_area_ieee754_bits INTEGER NOT NULL, fire_compartment_area_ieee754_class TEXT NOT NULL,
fire_compartment_height_ieee754_bits INTEGER NOT NULL, fire_compartment_height_ieee754_class TEXT NOT NULL,
fire_opening_factor_ieee754_bits INTEGER NOT NULL, fire_opening_factor_ieee754_class TEXT NOT NULL,
fire_thermal_inertia_ieee754_bits INTEGER NOT NULL, fire_thermal_inertia_ieee754_class TEXT NOT NULL,
fire_load_density_qf_ieee754_bits INTEGER NOT NULL, fire_load_density_qf_ieee754_class TEXT NOT NULL,
assumed_qf_d_ieee754_bits INTEGER NOT NULL, assumed_qf_d_ieee754_class TEXT NOT NULL,
assumed_construction_qk_ieee754_bits INTEGER NOT NULL, assumed_construction_qk_ieee754_class TEXT NOT NULL,
bridge_span_ieee754_bits INTEGER NOT NULL, bridge_span_ieee754_class TEXT NOT NULL,
bridge_lane_width_ieee754_bits INTEGER NOT NULL, bridge_lane_width_ieee754_class TEXT NOT NULL,
assumed_bridge_tandem_ieee754_bits INTEGER NOT NULL, assumed_bridge_tandem_ieee754_class TEXT NOT NULL,
assumed_bridge_udl_ieee754_bits INTEGER NOT NULL, assumed_bridge_udl_ieee754_class TEXT NOT NULL,
assumed_bridge_lm2_ieee754_bits INTEGER NOT NULL, assumed_bridge_lm2_ieee754_class TEXT NOT NULL,
assumed_bridge_footway_ieee754_bits INTEGER NOT NULL, assumed_bridge_footway_ieee754_class TEXT NOT NULL,
assumed_bridge_lm3_ieee754_bits INTEGER NOT NULL, assumed_bridge_lm3_ieee754_class TEXT NOT NULL,
assumed_bridge_lm4_ieee754_bits INTEGER NOT NULL, assumed_bridge_lm4_ieee754_class TEXT NOT NULL,
hoisting_speed_ieee754_bits INTEGER NOT NULL, hoisting_speed_ieee754_class TEXT NOT NULL,
assumed_crane_wheel_ieee754_bits INTEGER NOT NULL, assumed_crane_wheel_ieee754_class TEXT NOT NULL,
assumed_crane_horizontal_ieee754_bits INTEGER NOT NULL, assumed_crane_horizontal_ieee754_class TEXT NOT NULL,
silo_bulk_density_ieee754_bits INTEGER NOT NULL, silo_bulk_density_ieee754_class TEXT NOT NULL,
silo_height_ieee754_bits INTEGER NOT NULL, silo_height_ieee754_class TEXT NOT NULL,
silo_hydraulic_radius_ieee754_bits INTEGER NOT NULL, silo_hydraulic_radius_ieee754_class TEXT NOT NULL,
silo_mu_ieee754_bits INTEGER NOT NULL, silo_mu_ieee754_class TEXT NOT NULL,
silo_k_ieee754_bits INTEGER NOT NULL, silo_k_ieee754_class TEXT NOT NULL,
assumed_silo_pressure_ieee754_bits INTEGER NOT NULL, assumed_silo_pressure_ieee754_class TEXT NOT NULL,
assumed_silo_patch_ieee754_bits INTEGER NOT NULL, assumed_silo_patch_ieee754_class TEXT NOT NULL,
assumed_silo_wall_friction_ieee754_bits INTEGER NOT NULL, assumed_silo_wall_friction_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_floor(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, category TEXT NOT NULL, area REAL, assumed_qk REAL, assumed_qk_concentrated REAL, assumed_partitions REAL, area_ieee754_bits INTEGER NOT NULL, area_ieee754_class TEXT NOT NULL, assumed_qk_ieee754_bits INTEGER NOT NULL, assumed_qk_ieee754_class TEXT NOT NULL, assumed_qk_concentrated_ieee754_bits INTEGER NOT NULL, assumed_qk_concentrated_ieee754_class TEXT NOT NULL, assumed_partitions_ieee754_bits INTEGER NOT NULL, assumed_partitions_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_self_weight(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, material TEXT NOT NULL, thickness REAL, assumed_gk REAL, thickness_ieee754_bits INTEGER NOT NULL, thickness_ieee754_class TEXT NOT NULL, assumed_gk_ieee754_bits INTEGER NOT NULL, assumed_gk_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_roof(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, roof_type TEXT NOT NULL, pitch_deg REAL, c_e REAL, c_t REAL, has_parapet INTEGER NOT NULL CHECK(has_parapet IN (0,1)), parapet_height REAL, drift_obstruction_height REAL, multi_span INTEGER NOT NULL CHECK(multi_span IN (0,1)), assumed_sk REAL, pitch_deg_ieee754_bits INTEGER NOT NULL, pitch_deg_ieee754_class TEXT NOT NULL, c_e_ieee754_bits INTEGER NOT NULL, c_e_ieee754_class TEXT NOT NULL, c_t_ieee754_bits INTEGER NOT NULL, c_t_ieee754_class TEXT NOT NULL, parapet_height_ieee754_bits INTEGER NOT NULL, parapet_height_ieee754_class TEXT NOT NULL, drift_obstruction_height_ieee754_bits INTEGER NOT NULL, drift_obstruction_height_ieee754_class TEXT NOT NULL, assumed_sk_ieee754_bits INTEGER NOT NULL, assumed_sk_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_wind_face(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, zone TEXT NOT NULL, z REAL, c_pe10 REAL, c_pe1 REAL, c_pi REAL, c_s REAL, c_d REAL, loaded_area REAL, assumed_wp REAL, z_ieee754_bits INTEGER NOT NULL, z_ieee754_class TEXT NOT NULL, c_pe10_ieee754_bits INTEGER NOT NULL, c_pe10_ieee754_class TEXT NOT NULL, c_pe1_ieee754_bits INTEGER NOT NULL, c_pe1_ieee754_class TEXT NOT NULL, c_pi_ieee754_bits INTEGER NOT NULL, c_pi_ieee754_class TEXT NOT NULL, c_s_ieee754_bits INTEGER NOT NULL, c_s_ieee754_class TEXT NOT NULL, c_d_ieee754_bits INTEGER NOT NULL, c_d_ieee754_class TEXT NOT NULL, loaded_area_ieee754_bits INTEGER NOT NULL, loaded_area_ieee754_class TEXT NOT NULL, assumed_wp_ieee754_bits INTEGER NOT NULL, assumed_wp_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_accidental_case(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL);
CREATE TABLE en1991_impact(id INTEGER PRIMARY KEY, case_id INTEGER NOT NULL REFERENCES en1991_accidental_case(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), vehicle_mass REAL, vehicle_speed REAL, assumed_force REAL, vehicle_mass_ieee754_bits INTEGER NOT NULL, vehicle_mass_ieee754_class TEXT NOT NULL, vehicle_speed_ieee754_bits INTEGER NOT NULL, vehicle_speed_ieee754_class TEXT NOT NULL, assumed_force_ieee754_bits INTEGER NOT NULL, assumed_force_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_explosion(id INTEGER PRIMARY KEY, case_id INTEGER NOT NULL REFERENCES en1991_accidental_case(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), explosion_mass REAL, standoff REAL, assumed_pressure REAL, explosion_mass_ieee754_bits INTEGER NOT NULL, explosion_mass_ieee754_class TEXT NOT NULL, standoff_ieee754_bits INTEGER NOT NULL, standoff_ieee754_class TEXT NOT NULL, assumed_pressure_ieee754_bits INTEGER NOT NULL, assumed_pressure_ieee754_class TEXT NOT NULL);
